UPDATE public.source_chunks sc SET is_active=EXISTS (SELECT 1 FROM public.claim_chunks cc JOIN public.claims c ON c.id=cc.claim_id WHERE cc.chunk_id=sc.id AND c.review_status='approved' AND c.approval_origin='corpus_evidence_review');
TRUNCATE public.answer_cache,public.live_research_cache,public.web_search_cache;
DO $$ BEGIN IF (SELECT count(*) FROM public.claims WHERE review_status='approved' AND approval_origin='corpus_evidence_review') <> 269 THEN RAISE EXCEPTION 'active reviewed count mismatch'; END IF; END $$;
COMMIT;
